const optionMeasureCtx=(()=>{let c=document.createElement('canvas');return c.getContext('2d')})();
function optionVisualWidth(s){let t=docText(s);if(/[\n\r]/.test(t)||/<br/i.test(String(s)))return 99999;optionMeasureCtx.font='16px "Times New Roman"';let base=optionMeasureCtx.measureText(t.replace(/\$|\\[a-zA-Z]+|[{}]/g,'')).width,math=(String(s).match(/[\\_^{}]/g)||[]).length*5;return base+math+28}
function optionLayout(q){let vals=['A','B','C','D'].map(k=>optionVisualWidth(q.options[k]||''));if(vals.every(w=>w<=155))return 4;if(vals.every(w=>w<=330))return 2;return 1}
function optionTableXml(q){let cols=optionLayout(q),width=cols===4?Math.floor(W.usable/4):cols===2?Math.floor(W.usable/2):W.usable,rows=[];for(let i=0;i<4;i+=cols){rows.push(rowXml(Array.from({length:cols},(_,j)=>{let idx=i+j;if(idx>=4)return cellXml('',{width});let k=['A','B','C','D'][idx];return cellXml(pRuns([{t:`${k}. `,bold:true},{t:docText(q.options[k]||'')}],{align:'left',after:30}),{width,align:'left',margins:50})}),{noSplit:true}))}return tableXml(rows,Array(cols).fill(width),{borders:false,fixed:true})}
