const latexHeader=s=>String(s||'').replace(/([%&_#])/g,'\\$1');
function bm07Tex(ctx,v){let m=ctx.metadata,total=v.questions.length,point=total?10/total:0;return `\\documentclass[12pt,a4paper]{article}\n\\usepackage[utf8]{inputenc}\n\\usepackage[T5]{fontenc}\n\\usepackage[vietnamese]{babel}\n\\usepackage{amsmath,amssymb,geometry,enumitem,fancyhdr,multicol}\n\\geometry{margin=1.7cm}\n\\pagestyle{fancy}\\fancyhf{}\\fancyfoot[L]{Mã đề ${latexHeader(v.code)}}\\fancyfoot[R]{Trang \\thepage}\n\\begin{document}\n\\begin{center}{\\bfseries HỌC VIỆN CÔNG NGHỆ BƯU CHÍNH VIỄN THÔNG\\\\CƠ SỞ TẠI THÀNH PHỐ HỒ CHÍ MINH\\\\KHOA: ${latexHeader(m.faculty)} \\quad BỘ MÔN: ${latexHeader(m.department)}}\\vspace{3mm}\\\\{\\Large\\bfseries ĐỀ THI KẾT THÚC HỌC PHẦN}\\\\(Hình thức trắc nghiệm)\\end{center}\n\\noindent Kỳ thi: ${latexHeader(m.semester)} \\hfill Năm học: ${latexHeader(m.academic_year)}\\\\Học phần: ${latexHeader(activeSubject()?.name)} \\quad Mã học phần: ${latexHeader(m.course_code)}\\\\Ngày thi: ${latexHeader(viDate(m.exam_date))} \\quad Ca thi: ${latexHeader(m.shift)} \\quad Thời gian: ${m.duration_minutes} phút\\\\Nhóm thi: ${latexHeader(m.exam_groups)}\\\\\\textbf{Đề số: ${latexHeader(v.code)}}\\vspace{3mm}\n${v.questions.map((q,i)=>{let c=ctx.sets.clos.find(x=>x.id===q.clo_id),cols=optionLayout(q);let optsTex=['A','B','C','D'].map(k=>`\\textbf{${k}.} ${q.options[k]}`);let optionBlock=cols===4?`\\noindent ${optsTex.join('\\hfill ')}`:cols===2?`\\noindent ${optsTex[0]}\\hfill ${optsTex[1]}\\\\${optsTex[2]}\\hfill ${optsTex[3]}`:`${optsTex.join('\\\\')}`;return `\\noindent\\textbf{Câu ${i+1}.} (${latexHeader(c?.code)}: ${fmtNum(point)}đ) ${q.content}\n${optionBlock}`}).join('\n\\medskip\n')}\n\\begin{center}-- Hết --\\end{center}\n\\noindent Ghi chú: ${latexHeader(m.exam_note||'')}\\\\Họ tên SV: \\dotfill \\quad Lớp: \\dotfill \\quad Phòng thi: \\dotfill\\\\Ký tên: \\dotfill\\vspace{12mm}\n\\begin{minipage}{.48\\textwidth}\\centering\\textbf{TRƯỞNG BỘ MÔN DUYỆT ĐỀ THI}\\\\(Ký và ghi rõ họ tên)\\vspace{15mm}\\\\${latexHeader(m.head_of_department)}\\end{minipage}\\hfill\\begin{minipage}{.48\\textwidth}\\centering\\textbf{GIẢNG VIÊN RA ĐỀ}\\\\(Ký và ghi rõ họ tên)\\vspace{15mm}\\\\${latexHeader(m.lecturer)}\\end{minipage}\n\\end{document}`}
function bm08Body(ctx,v){let m=ctx.metadata,total=v.questions.length,point=total?10/total:0,body=[];body.push(pText('Mẫu BM08',{align:'right',bold:true,size:22}));body.push(pText(`Mẫu đáp án/hướng dẫn chấm (phiếu chấm theo CLO)-Mã đề ${v.code}`,{align:'center',bold:true,size:26,after:80}));body.push(pRuns([{t:'Tên học phần: ',bold:true},{t:activeSubject()?.name||''}],{after:25}));body.push(pRuns([{t:'Mã học phần: ',bold:true},{t:m.course_code||''}],{after:25}));body.push(pRuns([{t:'Số tín chỉ: ',bold:true},{t:String(m.credits||'')}],{after:25}));body.push(pRuns([{t:'Học kỳ/Năm học: ',bold:true},{t:`${m.semester||''}/${m.academic_year||''}`}],{after:25}));body.push(pRuns([{t:'Giảng viên ra đề: ',bold:true},{t:m.lecturer||''}],{after:25}));body.push(pRuns([{t:'Ngày thi: ',bold:true},{t:viDate(m.exam_date)},{t:'     Ca thi: ',bold:true},{t:m.shift||''}],{after:25}));body.push(pRuns([{t:'Hình thức thi: ',bold:true},{t:'Trắc nghiệm'}],{after:50}));body.push(pText('1. Đáp án & Thang điểm:',{bold:true,size:24}));body.push(pText(`Mỗi câu ${fmtNum(point)} điểm.`,{after:40}));let ansWidths=[1000,...Array(20).fill(450)],ansRows=[];for(let start=0;start<total;start+=20){let arr=v.questions.slice(start,start+20),cells=[cellXml('Câu',{width:1000})],ans=[cellXml('Đáp án',{width:1000})];arr.forEach((q,j)=>{cells.push(cellXml(String(start+j+1),{width:450}));ans.push(cellXml(q.correct_answer,{width:450}))});for(let k=arr.length;k<20;k++){cells.push(cellXml('',{width:450}));ans.push(cellXml('',{width:450}))}ansRows.push(rowXml(cells),rowXml(ans))}body.push(tableXml(ansRows,ansWidths));body.push(pText('2. Phiếu chấm theo CLO',{bold:true,size:24,before:50}));let cw=[850,3300,1500,1000,900,1050,1300],rows=[rowXml(['CLO','Nội dung đánh giá','Câu hỏi liên quan','Trọng số (%)','Điểm tối đa','Điểm đạt được','Nhận xét'].map((x,i)=>cellXml(x,{width:cw[i],bold:true})),{header:true})];ctx.sets.clos.forEach(c=>{let nums=v.questions.map((q,i)=>q.clo_id===c.id?i+1:null).filter(Boolean),n=nums.length;rows.push(rowXml([cellXml(c.code,{width:cw[0],bold:true}),cellXml(c.short_description||c.description||'',{width:cw[1],align:'center'}),cellXml(nums.length?`Câu ${nums.join(', ')}.`:'',{width:cw[2]}),cellXml(`${fmtNum(total?n*100/total:0,1)}%`,{width:cw[3]}),cellXml(fmtNum(n*point),{width:cw[4]}),cellXml('…',{width:cw[5]}),cellXml('',{width:cw[6]})],{height:800}))});body.push(tableXml(rows,cw));body.push(pText('Tổng điểm: ……/10',{align:'center',bold:true,before:30,after:60}));body.push(pText('3. Ghi chú cho giảng viên chấm thi',{bold:true,size:24}));['Chấm theo ý, không trừ điểm kiểu “lỗi chính tả” nếu không làm sai lệch nội dung.','Với ý trả lời tương đương (không giống đáp án nhưng đúng bản chất), giảng viên cho điểm tương ứng.','Điểm làm tròn đến 0,1.'].forEach(x=>body.push(pRuns([{t:'•  ',bold:true},{t:x}],{indent:300,after:25})));body.push(pText('TP.HCM, ngày ……… tháng…… năm 20…',{align:'right',italic:true,before:80}));body.push(tableXml([rowXml([cellXml([pText('TRƯỞNG BỘ MÔN',{align:'center',bold:true}),pText('(Ký và ghi rõ họ tên)',{align:'center',italic:true})],{width:5100}),cellXml([pText('GIẢNG VIÊN RA ĐỀ',{align:'center',bold:true}),pText('(Ký và ghi rõ họ tên)',{align:'center',italic:true})],{width:5100})])],[5100,5100],{borders:false}));return body.join('')}
