function answerWorkbook(ctx){let wb=XLSX.utils.book_new(),codes=ctx.variants.map(v=>v.code),n=Math.max(...ctx.variants.map(v=>v.questions.length)),rows=[];for(let i=0;i<n;i++){let r={'Câu':i+1};for(let v of ctx.variants){let q=v.questions[i],c=ctx.sets.clos.find(x=>x.id===q?.clo_id);r[v.code]=q?.correct_answer||'';r[`CLO_${v.code}`]=c?.code||''}rows.push(r)}let ws=XLSX.utils.json_to_sheet(rows,{header:['Câu',...codes.flatMap(c=>[c,`CLO_${c}`])]});XLSX.utils.book_append_sheet(wb,ws,'Doc');let horizontal=[];for(let v of ctx.variants){let ans={'Mã đề':v.code},clo={'Mã đề':`${v.code}_CLO`};v.questions.forEach((q,i)=>{ans[`Câu ${i+1}`]=q.correct_answer;clo[`Câu ${i+1}`]=ctx.sets.clos.find(c=>c.id===q.clo_id)?.code||''});horizontal.push(ans,clo)}XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(horizontal),'Ngang');return wb}
async function logFinalHistory(action,details={}){if(!finalCtx?.package?.id)return;try{let {error}=await db.from('final_exam_history').insert({package_id:finalCtx.package.id,subject_id:state.subjectId,actor_id:state.user.id,action,details});if(error&&!/does not exist|schema cache/i.test(error.message||''))console.warn('V10.4 history',error)}catch(e){console.warn('V10.4 history unavailable',e)}}
const historyActionLabel=a=>({created:'Tạo hồ sơ',updated:'Sửa hồ sơ',variants_generated:'Tạo mã đề',exported_bm06:'Xuất BM06',exported_bm07:'Xuất BM07',exported_bm08:'Xuất BM08',exported_answers:'Xuất đáp án CLO',exported_zip:'Xuất toàn bộ ZIP'}[a]||a);
async function loadFinalHistory(){let box=$('#finalHistoryBox');if(!box||!finalCtx?.package)return;try{let {data,error}=await db.from('final_exam_history').select('id,action,details,created_at,actor_id').eq('package_id',finalCtx.package.id).order('created_at',{ascending:false});if(error)throw error;let ids=[...new Set((data||[]).map(x=>x.actor_id))],names={};if(ids.length){let {data:ps}=await db.from('profiles').select('id,full_name,email').in('id',ids);for(let p of ps||[])names[p.id]=p.full_name||p.email||'Người dùng'}let rows=(data||[]).map(x=>`<div class="final-history-item"><span>${new Date(x.created_at).toLocaleString('vi-VN')}</span><b>${esc(names[x.actor_id]||'Người dùng')}</b><span>${esc(x.details?.label||historyActionLabel(x.action))}${x.details?.variant_code?` · Mã ${esc(x.details.variant_code)}`:''}</span></div>`).join('');box.innerHTML=rows||`<div class="final-history-item"><span>${new Date(finalCtx.package.created_at).toLocaleString('vi-VN')}</span><b>${esc(state.profile?.full_name||'Người tạo')}</b><span>Tạo hồ sơ</span></div>`}catch{box.innerHTML=`<p class="hint">Chạy <code>supabase/v10.4-upgrade.sql</code> để lưu lịch sử chi tiết. Hồ sơ tạo ${new Date(finalCtx.package.created_at).toLocaleString('vi-VN')}.</p>`}}
async function exportPackageZip(ctx){if(!window.JSZip)return toast('Không tải được thư viện ZIP',true);let zip=new JSZip();let b6=await bm06Docx(ctx);zip.file('BM06_Ma_tran_de_thi.docx',await b6.arrayBuffer());for(let v of ctx.variants){let b7=await bm07Docx(ctx,v),b8=await bm08Docx(ctx,v);zip.file(`BM07/BM07_De_${v.code}.docx`,await b7.arrayBuffer());zip.file(`BM07_TEX/De_${v.code}.tex`,bm07Tex(ctx,v));zip.file(`BM08/BM08_${v.code}.docx`,await b8.arrayBuffer())}let ab=XLSX.write(answerWorkbook(ctx),{bookType:'xlsx',type:'array'});zip.file('Dap_an_CLO.xlsx',ab);zip.file('README.txt','AI-CLO PTITHCM V10.4\nBM06/BM07/BM08 là DOCX thật. BM07 còn có TeX. Dap_an_CLO.xlsx dùng trực tiếp cho ứng dụng chấm thi CLO.');download(await zip.generateAsync({type:'blob'}),`Ho-so-de-thi-${fileSafe(activeSubject()?.name)}-${today()}.zip`);await logFinalHistory('exported_zip',{label:'Xuất toàn bộ hồ sơ ZIP'})}
async function showGeneratedPackage(){let ctx=finalCtx;if(!ctx?.variants?.length)return reviewFinalQuestions();questionWorkspace('Đã tạo bộ đề cuối kỳ',`${ctx.variants.length} mã đề · ${ctx.selected.length} câu · đã chốt.`,`<section class="panel v102-generated"><div class="panel-head"><div><h3>${esc(ctx.metadata.title)}</h3><div class="package-meta-line"><span>Đã tạo ${ctx.variants.length} mã đề</span><span>·</span><span>${esc(ctx.metadata.variant_codes?.join(', ')||'')}</span></div></div><span class="badge green">Đã tạo ${ctx.variants.length} mã đề</span></div><div class="variant-grid">${ctx.variants.map(v=>`<article><b>Mã đề ${esc(v.code)}</b><span>${v.questions.length} câu</span><button class="secondary" data-docx="${v.code}">BM07 DOCX</button><button class="secondary" data-tex="${v.code}">BM07 TeX</button><button class="secondary" data-bm08="${v.code}">BM08 DOCX</button></article>`).join('')}</div><div class="form-actions"><button id="downloadBM06" class="secondary">BM06 DOCX</button><button id="downloadAnswers" class="secondary">Dap_an_CLO.xlsx</button><button id="downloadFinalZip" class="primary">Tải toàn bộ hồ sơ ZIP</button>${(role()==='admin'||ctx.package?.created_by===state.user.id)?'<button id="deleteCurrentFinal" class="secondary danger-button">Xóa hồ sơ</button>':''}</div><p class="v104-docx-note">BM06/BM07/BM08 xuất DOCX thật bằng paragraph/table Word, không dùng Shift+Enter. BM07 tự chuyển phương án từ 1 dòng → 2 dòng → 4 dòng khi ô hẹp có nguy cơ xuống dòng.</p><div class="final-history"><div class="panel-head"><h3>Lịch sử hoạt động</h3><span class="hint">Ngày · người tạo/sửa/xuất</span></div><div id="finalHistoryBox" class="final-history-list"><p class="hint">Đang tải…</p></div></div></section>`);setFinalWorkspaceBack('← Quay lại chỉnh sửa đề',()=>{ctx.dirty=false;reviewFinalQuestions()});$$('[data-docx]').forEach(b=>b.onclick=async()=>{let v=ctx.variants.find(x=>x.code===b.dataset.docx);download(await bm07Docx(ctx,v),`BM07_De_${v.code}.docx`,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');await logFinalHistory('exported_bm07',{label:'Xuất BM07 DOCX',variant_code:v.code})});$$('[data-tex]').forEach(b=>b.onclick=async()=>{let v=ctx.variants.find(x=>x.code===b.dataset.tex);download(bm07Tex(ctx,v),`BM07_De_${v.code}.tex`,'text/plain;charset=utf-8');await logFinalHistory('exported_bm07',{label:'Xuất BM07 TeX',variant_code:v.code})});$$('[data-bm08]').forEach(b=>b.onclick=async()=>{let v=ctx.variants.find(x=>x.code===b.dataset.bm08);download(await bm08Docx(ctx,v),`BM08_${v.code}.docx`,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');await logFinalHistory('exported_bm08',{label:'Xuất BM08 DOCX',variant_code:v.code})});$('#downloadBM06').onclick=async()=>{download(await bm06Docx(ctx),'BM06_Ma_tran_de_thi.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');await logFinalHistory('exported_bm06',{label:'Xuất BM06 DOCX'})};$('#downloadAnswers').onclick=async()=>{XLSX.writeFile(answerWorkbook(ctx),'Dap_an_CLO.xlsx');await logFinalHistory('exported_answers',{label:'Xuất Dap_an_CLO.xlsx'})};$('#downloadFinalZip').onclick=()=>exportPackageZip(ctx);if($('#deleteCurrentFinal'))$('#deleteCurrentFinal').onclick=()=>deleteFinalPackage(ctx.package.id,ctx.metadata.title);loadFinalHistory()}
async function reopenPackage(id){let {data,error}=await db.from('final_exam_packages').select('*').eq('id',id).single();if(error)return err(error);let sets=await finalSets();finalCtx={sets,selected:data.selected_questions||[],metadata:data.metadata||{},matrix:data.matrix||[],source:data.source_scope,variants:data.variants||[],package:data,dirty:false,wasGenerated:data.status==='generated'||!!data.variants?.length};if(data.status==='reviewing')return reviewFinalQuestions();if(data.status==='draft'){localFinalDraft({metadata:data.metadata||{},matrix:data.matrix||[],source:data.source_scope,selected:data.selected_questions||[],stage:'matrix',package_id:data.id});return finalExamWizard()}showGeneratedPackage()}
async function deleteFinalPackage(id,title){if(!await confirmAction('Xóa hồ sơ đề thi?',`Xóa “${title||'đề thi'}”? Thao tác này xóa cả bản nháp/bộ mã đề đã lưu trên hệ thống.`,{confirmLabel:'Xóa'}))return;let {error}=await db.from('final_exam_packages').delete().eq('id',id);if(error)return err(error);let ld=readLocalFinalDraft();if(finalCtx?.package?.id===id||ld?.package_id===id){clearLocalFinalDraft();if(finalCtx?.package?.id===id)finalCtx=null}toast('Đã xóa hồ sơ đề thi');render()}

exams=async function(c){
 if(!canTeach())return onlineExams(c);
 await onlineExams(c);
 let toolbar=c.querySelector('.toolbar');if(toolbar){let b=document.createElement('button');b.id='createFinalExam';b.className='ai-btn';b.textContent='✎ Tạo đề thi cuối kỳ';toolbar.appendChild(b);b.onclick=()=>{finalCtx=null;finalExamWizard()}}
 let section=document.createElement('section');section.className='panel v102-final-list';section.innerHTML='<div class="panel-head"><h3>Hồ sơ đề thi cuối kỳ</h3><span class="hint">BM06 · BM07 · BM08 · đáp án CLO</span></div><div id="finalPackageRows"><p class="hint">Đang tải…</p></div>';c.appendChild(section);
 let {data,error}=await db.from('final_exam_packages').select('id,title,status,created_at,updated_at,created_by,metadata').eq('subject_id',state.subjectId).order('created_at',{ascending:false});if(error){$('#finalPackageRows').innerHTML=`<p class="hint">Chưa bật chức năng đề cuối kỳ. Chạy <code>supabase/v10.2-upgrade.sql</code>.</p>`;return}
 let ids=[...new Set((data||[]).map(x=>x.created_by))],names={};if(ids.length){let {data:ps}=await db.from('profiles').select('id,full_name,email').in('id',ids);for(let p of ps||[])names[p.id]=p.full_name||p.email||'Người dùng'}
 $('#finalPackageRows').innerHTML=(data||[]).map(x=>{let canDelete=role()==='admin'||x.created_by===state.user.id,status=x.status==='reviewing'?'Đang chỉnh sửa':x.status==='draft'?'Bản nháp':x.status==='generated'?`Đã tạo ${(x.metadata?.variant_codes||[]).length||4} mã đề`:x.status;return `<div class="final-package-row"><div><b>${esc(x.title)}</b><small>${new Date(x.created_at).toLocaleString('vi-VN')} · ${esc(names[x.created_by]||'Người tạo')} · Mã đề ${(x.metadata?.variant_codes||[]).join(', ')}</small>${x.updated_at&&x.updated_at!==x.created_at?`<small>Cập nhật: ${new Date(x.updated_at).toLocaleString('vi-VN')}</small>`:''}</div><span class="badge ${x.status==='generated'?'green':''}">${esc(status)}</span><div class="final-package-actions"><button class="secondary" data-open-final="${x.id}">${x.status==='generated'?'Mở / Sửa / Xuất':'Tiếp tục'}</button>${canDelete?`<button class="secondary danger-button" data-delete-final="${x.id}" data-title="${esc(x.title)}">Xóa</button>`:''}</div></div>`}).join('')||'<p class="hint">Chưa có bộ đề cuối kỳ.</p>';
 $$('[data-open-final]').forEach(b=>b.onclick=()=>reopenPackage(b.dataset.openFinal));$$('[data-delete-final]').forEach(b=>b.onclick=()=>deleteFinalPackage(b.dataset.deleteFinal,b.dataset.title));
};

